const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry: Taipei, Taiwan
  var taipei = ee.Geometry.Point(121.5654, 25.0330).buffer(10000); // 10km buffer

  // 2. Data: MODIS 8-day LST (MOD11A2)
  var modis = ee.ImageCollection('MODIS/006/MOD11A2');

  // Function to process LST image: scale, mask using QC
  function processLST(img) {
    var lst = img.select('LST_Day_1km').multiply(0.02).subtract(273.15); // to Celsius
    var qc = img.select('QC_Day');
    // Bits 0-1: 00=good, 01=ok, 10=cloud, 11=other. Keep 00 and 01.
    var mask = qc.bitwiseAnd(3).lte(1); // values 0 or 1
    return lst.updateMask(mask).rename('LST');
  }

  // 3. Historical: Jan 17-24 for each year 2001-2010
  var historicalYears = ee.List.sequence(2001, 2010);
  var historicalCollection = ee.ImageCollection.fromImages(
    historicalYears.map(function(year) {
      var start = ee.Date.fromYMD(year, 1, 17);
      var end = ee.Date.fromYMD(year, 1, 25); // exclusive
      return modis.filterDate(start, end)
                  .map(processLST)
                  .mean()
                  .set('year', year);
    })
  );

  // 4. 2016: Jan 17-24
  var start2016 = ee.Date.fromYMD(2016, 1, 17);
  var end2016 = ee.Date.fromYMD(2016, 1, 25);
  var collection2016 = modis.filterDate(start2016, end2016).map(processLST);

  // Check sizes
  var histSize = historicalCollection.size().getInfo();
  var size2016 = collection2016.size().getInfo();
  print('Historical images (years with data):', histSize);
  print('2016 images:', size2016);

  // If no data, try fallback to daily MOD11A1
  if (histSize === 0 || size2016 === 0) {
    print('Trying MOD11A1 (daily) as fallback...');
    var modisDaily = ee.ImageCollection('MODIS/006/MOD11A1');
    // Reprocess for daily: same processing, but need to composite over date range
    function processDaily(img) {
      var lst = img.select('LST_Day_1km').multiply(0.02).subtract(273.15);
      var qc = img.select('QC_Day');
      var mask = qc.bitwiseAnd(3).lte(1);
      return lst.updateMask(mask).rename('LST');
    }
    // Historical: for each year, filter date range and composite
    historicalCollection = ee.ImageCollection.fromImages(
      historicalYears.map(function(year) {
        var start = ee.Date.fromYMD(year, 1, 17);
        var end = ee.Date.fromYMD(year, 1, 25);
        return modisDaily.filterDate(start, end)
                         .map(processDaily)
                         .mean()
                         .set('year', year);
      })
    );
    collection2016 = modisDaily.filterDate(start2016, end2016).map(processDaily);
    histSize = historicalCollection.size().getInfo();
    size2016 = collection2016.size().getInfo();
    print('After fallback - Historical images:', histSize);
    print('After fallback - 2016 images:', size2016);
  }

  // If still no data, output C1
  if (histSize === 0 || size2016 === 0) {
    print('<answer>C1</answer>');
    return;
  }

  // Compute mean LST images over each collection
  var histMean = historicalCollection.mean();
  var img2016 = collection2016.mean();

  // Compute region statistics: mean temperature and pixel count
  var histStats = histMean.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taipei,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();
  var histLST = histStats['LST'];
  var histCount = histStats['LST_count'];

  var stats2016 = img2016.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taipei,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();
  var lst2016 = stats2016['LST'];
  var count2016 = stats2016['LST_count'];

  print('Historical (2001-2010 avg) LST (°C):', histLST, 'Valid pixels:', histCount);
  print('2016 LST (°C):', lst2016, 'Valid pixels:', count2016);

  // Check for no valid pixels
  if (histCount === 0 || count2016 === 0) {
    print('<answer>C2</answer>');
    return;
  }

  // Validate LST values (reasonable range for Taipei in January: maybe -10 to 30°C)
  if (histLST === null || lst2016 === null ||
      histLST < -50 || histLST > 50 ||
      lst2016 < -50 || lst2016 > 50) {
    print('<answer>C3</answer>');
    return;
  }

  // Compare: if 2016 temperature is lower (decrease)
  if (lst2016 < histLST) {
    print('<answer>A</answer>');
  } else {
    print('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
